import{_ as t,o as a,c as i,an as s}from"./chunks/framework.DHjvKR4f.js";const g=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/index.md","filePath":"getting-started/index.md","lastUpdated":null}'),n={name:"getting-started/index.md"};function d(l,e,o,r,h,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started {#getting-started}&quot;">​</a></h1><p><code>reparameterise</code> wraps a Distributions.jl family so that its moments are its parameters. This page covers what the wrapper does, which parameterisations are registered, and how to rescale one.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ReparameterisedDistributions, Distributions</span></span></code></pre></div><h2 id="A-first-example" tabindex="-1">A first example <a class="header-anchor" href="#A-first-example" aria-label="Permalink to &quot;A first example {#A-first-example}&quot;">​</a></h2><p>A delay can be elicited as a mean and a standard deviation. A prior belongs on that mean, not on a shape parameter that only implies it. <code>reparameterise</code> wraps a native family so that the moments are its parameters.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> reparameterise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(LogNormal; mean </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, sd </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">reparameterise(Distributions.LogNormal; mean = 8.0, sd = 2.0)</span></span>
<span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">  native: Distributions.LogNormal{Float64}(μ=2.0491292307716185, σ=0.24622067706923975)</span></span></code></pre></div><p><code>params</code> reports the moments, not the native <code>(mu, sigma)</code>. Every other method works exactly as it would on the native distribution.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">params</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(d), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">mean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(d), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(d), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">logpdf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(d, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">7.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">((8.0, 2.0), 7.999999999999998, 1.9999999999999996, -1.5419758370451855)</span></span></code></pre></div><p>The wrapper takes its variate form and value support from the family it wraps, so a wrapped discrete family stays discrete.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nb </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> reparameterise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(NegativeBinomial; mean </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, overdispersion </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">mean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(nb), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(nb))</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">(10.000000000000002, 60.00000000000001)</span></span></code></pre></div><h2 id="Invalid-moments" tabindex="-1">Invalid moments <a class="header-anchor" href="#Invalid-moments" aria-label="Permalink to &quot;Invalid moments {#Invalid-moments}&quot;">​</a></h2><p>Constraining each moment on its own does not always keep the combination attainable. A <code>Beta</code> needs <code>sd^2 &lt; mean * (1 - mean)</code>, so a positive mean and a positive standard deviation can still describe no <code>Beta</code> at all. <code>check_args = false</code> turns the constructor check off, so a proposal like that gives <code>logpdf == -Inf</code> rather than raising mid-gradient.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bad </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> reparameterise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Beta; mean </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, sd </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, check_args </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">logpdf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(bad, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">-Inf</span></span></code></pre></div><p>Every other method still converts, so an invalid distribution has no mean, no quantile and no draw. Asking for one raises.</p><h2 id="Supported-parameterisations" tabindex="-1">Supported parameterisations <a class="header-anchor" href="#Supported-parameterisations" aria-label="Permalink to &quot;Supported parameterisations {#Supported-parameterisations}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Family</th><th style="text-align:right;">Parameters</th><th style="text-align:right;">Conversion</th></tr></thead><tbody><tr><td style="text-align:right;"><code>LogNormal</code></td><td style="text-align:right;"><code>mean</code>, <code>sd</code></td><td style="text-align:right;">the moments of the distribution, not of its logarithm</td></tr><tr><td style="text-align:right;"><code>LogNormal</code></td><td style="text-align:right;"><code>mean</code>, <code>var</code></td><td style="text-align:right;">as above, given the variance</td></tr><tr><td style="text-align:right;"><code>Gamma</code></td><td style="text-align:right;"><code>mean</code>, <code>sd</code></td><td style="text-align:right;"><code>scale = var / mean</code>, <code>shape = mean² / var</code></td></tr><tr><td style="text-align:right;"><code>Gamma</code></td><td style="text-align:right;"><code>mean</code>, <code>var</code></td><td style="text-align:right;">as above, given the variance</td></tr><tr><td style="text-align:right;"><code>Gamma</code></td><td style="text-align:right;"><code>mean</code>, <code>shape</code></td><td style="text-align:right;"><code>scale = mean / shape</code>; the shape is native</td></tr><tr><td style="text-align:right;"><code>Gamma</code></td><td style="text-align:right;"><code>shape</code>, <code>rate</code></td><td style="text-align:right;"><code>scale = 1 / rate</code>; the shape is native</td></tr><tr><td style="text-align:right;"><code>NegativeBinomial</code></td><td style="text-align:right;"><code>mean</code>, <code>overdispersion</code></td><td style="text-align:right;"><code>var = mean + overdispersion · mean²</code></td></tr><tr><td style="text-align:right;"><code>NegativeBinomial</code></td><td style="text-align:right;"><code>mean</code>, <code>dispersion</code></td><td style="text-align:right;"><code>var = mean + mean² / dispersion</code>, the reciprocal convention</td></tr><tr><td style="text-align:right;"><code>Exponential</code></td><td style="text-align:right;"><code>rate</code></td><td style="text-align:right;"><code>scale = 1 / rate</code></td></tr><tr><td style="text-align:right;"><code>SkewNormal</code></td><td style="text-align:right;"><code>centre</code>, <code>scale</code>, <code>mass_below_centre</code></td><td style="text-align:right;"><code>alpha = tan(π · (1/2 − mass_below_centre))</code></td></tr><tr><td style="text-align:right;"><code>Beta</code></td><td style="text-align:right;"><code>mean</code>, <code>sd</code></td><td style="text-align:right;"><code>nu = mean·(1−mean)/var − 1</code>; <code>alpha = mean·nu</code>, <code>beta = (1−mean)·nu</code></td></tr><tr><td style="text-align:right;"><code>Beta</code></td><td style="text-align:right;"><code>mean</code>, <code>var</code></td><td style="text-align:right;">as above, given the variance</td></tr><tr><td style="text-align:right;"><code>InverseGaussian</code></td><td style="text-align:right;"><code>mean</code>, <code>sd</code></td><td style="text-align:right;"><code>lambda = mean³ / var</code>; the mean is native</td></tr><tr><td style="text-align:right;"><code>InverseGaussian</code></td><td style="text-align:right;"><code>mean</code>, <code>var</code></td><td style="text-align:right;">as above, given the variance</td></tr><tr><td style="text-align:right;"><code>Weibull</code></td><td style="text-align:right;"><code>mean</code>, <code>sd</code></td><td style="text-align:right;">numeric: the CV pins the shape by a scalar root-find; the scale then follows in closed form</td></tr><tr><td style="text-align:right;"><code>Weibull</code></td><td style="text-align:right;"><code>mean</code>, <code>var</code></td><td style="text-align:right;">as above, given the variance</td></tr></tbody></table><p><code>Weibull(mean, sd)</code> has no exact closed form. The coefficient of variation depends on the shape alone, through a strictly monotone one-dimensional equation that a bracketing root-find solves, with the scale then following in closed form. The gradient is still exact: the root&#39;s derivative is recovered afterwards by an implicit-function-theorem correction rather than by differentiating through the solver.</p><p>Registering a family, analytic or numeric, needs exactly one <code>to_native</code> method: the conversion, guarding its own validity first and returning <code>nothing</code> for a value its parameters cannot describe. A family with no exact closed form calls <code>solve_moment</code> from inside its own <code>to_native</code>, passing its moment equation, its derivative and a bracket as ordinary functions, after the same guard.</p><p>Register the method under the parameter names sorted alphabetically: <code>reparameterise</code> canonicalises its keywords that way before dispatching, so a method registered under <code>Val((:sd, :mean))</code> is never found. The <a href="/v0.2/lib/public#public-api">Public API</a> documents the hook.</p><h2 id="Rescaling-a-moment" tabindex="-1">Rescaling a moment <a class="header-anchor" href="#Rescaling-a-moment" aria-label="Permalink to &quot;Rescaling a moment {#Rescaling-a-moment}&quot;">​</a></h2><p><code>rescale(d, factor)</code> scales one of <code>d</code>&#39;s registered moments by <code>factor</code>, holding the others fixed. It routes through whichever parameterisation <code>d</code> was built under.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> reparameterise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Gamma; mean </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, shape </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">mean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(g), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">mean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">rescale</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(g, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)))</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">(8.0, 16.0)</span></span></code></pre></div><p>The shape stays at 2.0 and only the mean moves. A discrete family scales in moment coordinates rather than by an affine transform of the native support.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">mean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">rescale</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(nb, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;">30.0</span></span></code></pre></div><p><code>parameter</code> defaults to <code>:mean</code> and can name any of <code>d</code>&#39;s registered parameters. Naming one that is not registered for <code>d</code>&#39;s family raises a <code>DomainError</code> rather than applying the factor under different semantics.</p><h2 id="Learning-more" tabindex="-1">Learning more <a class="header-anchor" href="#Learning-more" aria-label="Permalink to &quot;Learning more {#Learning-more}&quot;">​</a></h2><ul><li><p>Work through <a href="/v0.2/getting-started/tutorials/priors-on-moments#priors-on-moments">Priors on moments</a> to see what a prior on a moment implies in native coordinates, and how to fit one.</p></li><li><p>Want the full interface? See the <a href="/v0.2/lib/public#public-api">Public API</a>.</p></li><li><p>Want to report a problem or ask a question? Open an issue or start a discussion on the <a href="https://github.com/EpiAware/ReparameterisedDistributions.jl" target="_blank" rel="noreferrer">GitHub repository</a>.</p></li></ul><p>The layout, navigation, and infrastructure of this site are generated by <a href="https://epiawarepackagetools.epiaware.org" target="_blank" rel="noreferrer">EpiAwarePackageTools</a>. Its docs cover customising the generated pages and how template sync keeps this repository current.</p>`,34)])])}const k=t(n,[["render",d]]);export{g as __pageData,k as default};
